1	/**
2	 * The whole screen: the launchpad, and the map you open from it.
3	 *
4	 * Two states and nothing in between. The launchpad names the two ways into the
5	 * tool and offers the four examples from the brief; opening the one that is
6	 * built swaps the page for the map. Everything on the map came over the wire
7	 * from the server, and the line under it says which address it came from — this
8	 * product does not put a number on screen that a reader cannot trace to an
9	 * input, a rule or a source, and that includes numbers a stored example happens
10	 * to carry.
11	 *
12	 * There is no spinner anywhere, and there never will be. A spinner says "wait"
13	 * without saying what for. While something is on its way the screen says what
14	 * it is waiting for and where it asked.
15	 */
16	
17	import { useCallback, useEffect, useMemo, useState } from "react";
18	import type { About, FixtureSummary, Health, Readiness } from "./api/client";
19	import { readAbout, readExampleList, readHealth, readReadiness } from "./api/client";
20	import type { Asked } from "./components/InputBar";
21	import { Launchpad } from "./components/Launchpad";
22	import { MapScreen } from "./components/MapScreen";
23	import { GenerationScreen } from "./stream/GenerationScreen";
24	import type { TheRun } from "./stream/theRun";
25	import { askForAMap } from "./stream/theRun";
26	import {
27	  ApiWorldSource,
28	  type BranchView,
29	  branchesOf,
30	  FixtureWorldSource,
31	  type WorldSource,
32	  type WorldView,
33	} from "./world";
34	import { asOneSentence } from "./world/failures";
35	import { countInWords } from "./world/naming";
36	
37	/**
38	 * Everything the screen can know about one thing it asked for. Three states and
39	 * no others, which is what makes every pixel below traceable to a cause.
40	 */
41	type Answer<Reading> =
42	  | { state: "asking" }
43	  | { state: "answered"; value: Reading }
44	  | { state: "failed"; reason: string };
45	
46	/** How loud a row's words are. Emphasis only — the words carry the meaning. */
47	type Tone = "good" | "quiet" | "loud";
48	
49	/** One row of the strip at the foot of the launchpad. */
50	interface Reading {
51	  /** What is being reported, such as "server". */
52	  label: string;
53	  /** The value from the server, or null while the request is still in flight. */
54	  value: string | null;
55	  /** A mark beside the words. Never the only carrier of meaning. */
56	  glyph: string;
57	  /** What the value means, in plain words. On a failure, this is the failure. */
58	  state: string;
59	  tone: Tone;
60	}
61	
62	/**
63	 * Ask what this copy can do.
64	 *
65	 * Defined at module level because the hook below runs it once and needs the
66	 * same function on every render.
67	 *
68	 * **It reads the generated description of the server and nothing else.** The
69	 * two fields the first screen lives on — which examples can be played, and one
70	 * sentence per recording this engine could not read — were written out by hand
71	 * here for as long as the route that owns them was being built beside this
72	 * half. They are in `schema.ts` now, so the hand-written copy is gone: two
73	 * descriptions of one answer eventually disagree, and the generated one is the
74	 * server's own.
75	 */
76	function askReadiness(): Promise<Readiness> {
77	  return readReadiness();
78	}
79	
80	/**
81	 * Make one request when the screen first appears and report where it got to.
82	 *
83	 * @param ask The request to make. It must be the same function on every render,
84	 *   so pass one defined at module level rather than one written inline.
85	 */
86	function useAnswer<Reading>(ask: () => Promise<Reading>): Answer<Reading> {
87	  const [answer, setAnswer] = useState<Answer<Reading>>({ state: "asking" });
88	
89	  useEffect(() => {
90	    let stillOnScreen = true;
91	    ask().then(
92	      (value) => {
93	        if (stillOnScreen) {
94	          setAnswer({ state: "answered", value });
95	        }
96	      },
97	      (reason: unknown) => {
98	        if (stillOnScreen) {
99	          setAnswer({ state: "failed", reason: asOneSentence(reason) });
100	        }
101	      },
102	    );
103	    return () => {
104	      stillOnScreen = false;
105	    };
106	  }, [ask]);
107	
108	  return answer;
109	}
110	
111	/**
112	 * Whether the server answered, and which build answered — in one quiet line.
113	 *
114	 * **They were two rows of the strip, and they are two facts a reader of this
115	 * screen is not making a decision about.** A route name and a build number
116	 * under the first screen make a take-home read as an implementation showcase at
117	 * the moment it should read as a decision tool. Nothing is lost: both readings
118	 * are still here, still the server's own, still traceable to the address the
119	 * line under them names. They are simply not given the weight of a labelled row
120	 * beside the one reading that changes what a reader can do, which is whether
121	 * there is a model key.
122	 *
123	 * Each half says where it has got to for itself, so a failure of one is not
124	 * hidden by the other answering.
125	 *
126	 * @param health What `/api/healthz` said, or where that question has got to.
127	 * @param about What `/api/about` said, or where that question has got to.
128	 */
129	function serverAndBuild(health: Answer<Health>, about: Answer<About>): string {
130	  const reachable =
131	    health.state === "asking"
132	      ? "Asking the server whether it is there."
133	      : health.state === "answered"
134	        ? `Server ${health.value.status}.`
135	        : health.reason;
136	  const build =
137	    about.state === "asking"
138	      ? "Asking which build answered."
139	      : about.state === "answered"
140	        ? `Build ${about.value.version}, reported by ${about.value.name}.`
141	        : about.reason;
142	  return `${reachable} ${build}`;
143	}
144	
145	/** The row that says whether a key for the language model is configured. */
146	function modelKeyReading(answer: Answer<Readiness>): Reading {
147	  switch (answer.state) {
148	    case "asking":
149	      return {
150	        label: "model key",
151	        value: null,
152	        glyph: "○",
153	        state: "asking the server",
154	        tone: "quiet",
155	      };
156	    case "answered":
157	      return answer.value.model_key_present
158	        ? {
159	            label: "model key",
160	            value: "present",
161	            glyph: "●",
162	            state: "ready to generate",
163	            tone: "good",
164	          }
165	        : {
166	            label: "model key",
167	            value: "absent",
168	            glyph: "○",
169	            state:
170	              answer.value.replayable.length === 0
171	                ? "no key configured, and nothing recorded to play instead"
172	                : `no key configured — ${countInWords(answer.value.replayable.length)} ` +
173	                  `${answer.value.replayable.length === 1 ? "example plays" : "examples play"} ` +
174	                  `from recordings`,
175	            tone: "quiet",
176	          };
177	    case "failed":
178	      return { label: "model key", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
179	  }
180	}
181	
182	/**
183	 * One row: a label, the value the server gave, and what that value means.
184	 *
185	 * While the value is missing the cell holds a bar of the same height, so the
186	 * row does not change size when the answer arrives. There is no spinner: a bar
187	 * where the value will land says the same thing without pretending to spin.
188	 */
189	function StatusRow({ reading }: { reading: Reading }) {
190	  const waiting = reading.value === null;
191	  return (
192	    <div className="status-row">
193	      <dt className="status-label">{reading.label}</dt>
194	      <dd className="status-value" data-settled={waiting ? "no" : "yes"}>
195	        {waiting ? <span className="placeholder" aria-hidden="true" /> : reading.value}
196	      </dd>
197	      <dd className="status-state" data-tone={reading.tone}>
198	        <span className="glyph" aria-hidden="true">
199	          {reading.glyph}
200	        </span>
201	        <span className="state-words">{reading.state}</span>
202	      </dd>
203	    </div>
204	  );
205	}
206	
207	/** Which of the screens is showing. */
208	type Screen =
209	  | { at: "launchpad" }
210	  | { at: "opening"; id: string }
211	  /**
212	   * A map being built in front of the reader, from a sentence they typed.
213	   *
214	   * **The run is here, not inside the screen**, because the press that made this
215	   * state is what asked for it. A screen that asked on mount would ask twice in
216	   * development, where React mounts every screen, unmounts it and mounts it
217	   * again on purpose — and *"never retry, a generation that ran twice would
218	   * spend twice"* would be broken on every machine this product is built on.
219	   */
220	  | { at: "growing"; run: TheRun }
221	  | {
222	      at: "map";
223	      world: WorldView;
224	      branches: readonly BranchView[];
225	      /**
226	       * Why the map on screen was read from the stored example rather than
227	       * worked out by the engine, or nothing when the engine answered.
228	       */
229	      insteadOfTheEngine: string | null;
230	    }
231	  | { at: "failed"; id: string; reason: string };
232	
233	/**
234	 * Where maps come from: the engine.
235	 *
236	 * Every number on the map is worked out by it, from the stored map, the branch
237	 * and one seed. Nothing on this screen computes a likelihood, and nothing on
238	 * this screen shows one the engine did not produce.
239	 */
240	const DEFAULT_SOURCE: WorldSource = new ApiWorldSource();
241	
242	/**
243	 * Where maps come from when the engine cannot be reached.
244	 *
245	 * A map you can still read beats a blank screen. The stored example's claims,
246	 * arrows, dates and sources are all real and all still worth reading — what is
247	 * missing is the working-out, and the screen says so in a line under the map
248	 * rather than letting a hand-written likelihood pass for a computed one.
249	 */
250	const FALLBACK_SOURCE: WorldSource = new FixtureWorldSource();
251	
252	/**
253	 * The line under the map when the stored example is standing in for the engine.
254	 *
255	 * @param reason What went wrong, in the sentence the failure arrived with.
256	 */
257	function insteadOfTheEngine(reason: string): string {
258	  return (
259	    `The engine did not answer, so this map is the stored example exactly as it was written: ` +
260	    `its claims, arrows, dates and sources are real, and its likelihoods are the illustrative ` +
261	    `ones somebody wrote down rather than anything worked out. ${reason}`
262	  );
263	}
264	
265	/** What the screen needs. All three have defaults; all three exist so they can be swapped. */
266	export interface AppProps {
267	  /** Where maps and worlds come from. */
268	  readonly source?: WorldSource;
269	  /** Where they come from when the first one cannot answer. */
270	  readonly fallback?: WorldSource;
271	  /** How the list of stored examples is read. */
272	  readonly listExamples?: () => Promise<FixtureSummary[]>;
273	}
274	
275	/** The screen. */
276	export function App({
277	  source = DEFAULT_SOURCE,
278	  fallback = FALLBACK_SOURCE,
279	  listExamples = readExampleList,
280	}: AppProps = {}) {
281	  const health = useAnswer(readHealth);
282	  const readiness = useAnswer(askReadiness);
283	  const about = useAnswer(readAbout);
284	  const examples = useAnswer(listExamples);
285	
286	  const [screen, setScreen] = useState<Screen>({ at: "launchpad" });
287	  const [using, setUsing] = useState<WorldSource>(source);
288	
289	  const open = useCallback(
290	    (id: string) => {
291	      setScreen({ at: "opening", id });
292	      /**
293	       * The world and the map's own branches, together: the world is what gets
294	       * drawn, and the branches are the edits somebody already made to it, which
295	       * the panel lists and the diff view folds on.
296	       *
297	       * @param from Where to ask.
298	       */
299	      const ask = (from: WorldSource) =>
300	        Promise.all([from.readWorld({ baseId: id }), from.readBundle(id)]);
301	
302	      ask(source).then(
303	        ([world, bundle]) => {
304	          setUsing(source);
305	          setScreen({ at: "map", world, branches: branchesOf(bundle), insteadOfTheEngine: null });
306	        },
307	        (failure: unknown) => {
308	          // The engine could not answer. Rather than a blank screen, the stored
309	          // example — and a line under the map saying, in the failure's own
310	          // words, that these are not computed numbers.
311	          ask(fallback).then(
312	            ([world, bundle]) => {
313	              setUsing(fallback);
314	              setScreen({
315	                at: "map",
316	                world,
317	                branches: branchesOf(bundle),
318	                insteadOfTheEngine: insteadOfTheEngine(asOneSentence(failure)),
319	              });
320	            },
321	            // Neither answered, which means the server itself is not there. That
322	            // is one sentence on the page, and a way back to the launchpad.
323	            (alsoFailed: unknown) =>
324	              setScreen({ at: "failed", id, reason: asOneSentence(alsoFailed) }),
325	          );
326	        },
327	      );
328	    },
329	    [source, fallback],
330	  );
331	
332	  const toLaunchpad = useCallback(() => setScreen({ at: "launchpad" }), []);
333	
334	  /**
335	   * Build a map from a sentence, and watch it arrive.
336	   *
337	   * **The request goes from here**, inside the press. Not from a render and not
338	   * from an effect: an effect runs twice in development by design, and this is
339	   * the one request in the product where running twice means paying twice.
340	   */
341	  const build = useCallback((asked: Asked) => {
342	    setScreen({ at: "growing", run: askForAMap(asked) });
343	  }, []);
344	
345	  /**
346	   * Leave a generation: let go of it first, then go back.
347	   *
348	   * Letting go is what stops the spending — the route checks whether the client
349	   * is still there before its next model call — and it is done here, in the
350	   * press, rather than when the screen unmounts, for the same reason the run is
351	   * started in a press: a development-mode unmount would stop a run nobody left.
352	   */
353	  const leaveTheRun = useCallback(
354	    (run: TheRun) => () => {
355	      run.letGo();
356	      setScreen({ at: "launchpad" });
357	    },
358	    [],
359	  );
360	
361	  /** Ask the same question again, which is a new run and a new screen. */
362	  const runAgain = useCallback(
363	    (run: TheRun) => () => {
364	      run.letGo();
365	      setScreen({ at: "growing", run: askForAMap(run.asked) });
366	    },
367	    [],
368	  );
369	
370	  // **One labelled row, and one quiet line.** The row is the model key, because
371	  // it is the one reading on this screen that changes what a reader can do — it
372	  // is why a sentence has a recording behind it or nothing at all. Whether the
373	  // server answered and which build answered are still here, in the line under
374	  // it, where they are traceable without being the first thing read.
375	  const readings = useMemo(() => [modelKeyReading(readiness)], [readiness]);
376	  const behind = useMemo(() => serverAndBuild(health, about), [health, about]);
377	
378	  if (screen.at === "growing") {
379	    return (
380	      <GenerationScreen
381	        // Named by the press that asked for it, so that asking the same question
382	        // again draws a fresh screen rather than a second map inside the first
383	        // one's selection and focus.
384	        key={screen.run.press}
385	        run={screen.run}
386	        // Known before the stream has said anything, which is the whole reason
387	        // the badge can be on screen from the first frame. When the receipt
388	        // arrives it is the authority, and the badge takes its word.
389	        replaying={readiness.state === "answered" && !readiness.value.model_key_present}
390	        onRunAgain={runAgain(screen.run)}
391	        onLeave={leaveTheRun(screen.run)}
392	      />
393	    );
394	  }
395	
396	  if (screen.at === "map") {
397	    return (
398	      <MapScreen
399	        base={screen.world}
400	        branches={screen.branches}
401	        source={using}
402	        insteadOfTheEngine={screen.insteadOfTheEngine}
403	        onLeave={toLaunchpad}
404	      />
405	    );
406	  }
407	
408	  if (screen.at !== "launchpad") {
409	    return (
410	      <main className="page page--map">
411	        <header className="map-bar">
412	          <button className="map-bar__back" type="button" onClick={toLaunchpad}>
413	            <span aria-hidden="true">←</span> Back to the launchpad
414	          </button>
415	          <h1 className="map-bar__title">Strait of Hormuz</h1>
416	        </header>
417	
418	        <div className="map-waiting">
419	          <p className="map-waiting__line">
420	            {screen.at === "opening"
421	              ? `Reading the map from /api/fixtures/${screen.id} and asking /api/worlds to work ` +
422	                `its likelihoods through.`
423	              : screen.reason}
424	          </p>
425	        </div>
426	      </main>
427	    );
428	  }
429	
430	  return (
431	    <main className="page">
432	      {/* The first screen is the one wide column in this product: it holds the
433	          two doors, a map that is already drawn, the four sentences from the
434	          brief and the field you type your own into, and stacking all of that
435	          in the 660-pixel measure the rest of the page reads at pushes the
436	          field below the fold. `launchpad.css` owns the width. */}
437	      <div className="column column--launchpad">
438	        <header className="masthead">
439	          <h1 className="wordmark">Katalyst</h1>
440	          <p className="purpose">
441	            Type an event you think will happen. See what it would cause, step by step, ending in
442	            trades.
443	          </p>
444	        </header>
445	
446	        <Launchpad
447	          examples={examples.state === "answered" ? examples.value : null}
448	          failure={examples.state === "failed" ? examples.reason : null}
449	          readiness={readiness.state === "answered" ? readiness.value : null}
450	          // **An absent answer is two different facts and the screen is handed
451	          // both.** Without this, a readiness request that failed looked exactly
452	          // like one still in flight, and the first screen said *asking the
453	          // server* for ever over an ask that had ended — while the strip below
454	          // it printed the failure's own sentence. A screen asserting a question
455	          // that is not being asked is a state nobody can trace to an input.
456	          readinessFailure={readiness.state === "failed" ? readiness.reason : null}
457	          onOpen={open}
458	          onBuild={build}
459	        />
460	
461	        <section aria-labelledby="status-heading">
462	          <h2 className="section-heading" id="status-heading">
463	            What this build can do right now
464	          </h2>
465	          <dl className="status-strip">
466	            {readings.map((reading) => (
467	              <StatusRow key={reading.label} reading={reading} />
468	            ))}
469	          </dl>
470	          <p className="provenance">{behind}</p>
471	          <p className="provenance">
472	            Every reading above came from the server, at <code>/api/healthz</code>,{" "}
473	            <code>/api/readyz</code> and <code>/api/about</code>. The examples came from{" "}
474	            <code>/api/fixtures</code>. Nothing on this screen is written into the page.
475	          </p>
476	        </section>
477	      </div>
478	    </main>
479	  );
480	}
