151	/**
152	 * Point at one arrow and open the six things you can do to it.
153	 *
154	 * **Two ways in, both retried, and the failure says which one got how far.** An
155	 * arrow is a curve: the middle of the box around it is usually a tile, and part
156	 * of the curve itself runs under one, so the spot to point at has to be looked
157	 * for rather than worked out. And the keyboard's way in — stand on the arrow
158	 * and press Enter — needs the standing to have taken, which a rebuild of the
159	 * arrow's element undoes. Either alone left this step failing about once in a
160	 * hundred and sixty runs; what is retried is the asking, and what is waited for
161	 * is the panel naming the arrow.
162	 *
163	 * @param page The page the map is on.
164	 * @param id The arrow, by the identifier it carries on the glass.
165	 */
166	async function openThePanelOnTheArrow(page: Page, id: string): Promise<void> {
167	  const arrow = page.locator(`.react-flow__edge[data-id="${id}"]`);
168	  const panel = page.locator(".intervene");
169	  const tried: string[] = [];
170	  // **The arrow is on the glass, or this fails here and says which arrow.**
171	  // This used to wait the missing arrow out and report what each attempt saw,
172	  // because the map really did lose one under load — a tile whose ports the
173	  // drawing library never measured has no arrows drawn to it. The ports are
174	  // declared rather than measured now, so the waiting is gone: if it ever comes
175	  // back, this is where it says so, by name, in fifteen seconds rather than
176	  // forty-five.
177	  await expect(arrow).toHaveCount(1);
178	
179	  const until = Date.now() + 45_000;
180	  while (Date.now() < until) {
181	    const on = await arrow.evaluate((group, which) => {
182	      const line = group.querySelector("path") as SVGPathElement | null;
183	      const toTheScreen = line?.getScreenCTM();
184	      if (line === null || toTheScreen === null || toTheScreen === undefined) {
185	        return null;
186	      }
187	      const total = line.getTotalLength();
188	      for (let step = 1; step < 40; step += 1) {
189	        const along = line.getPointAtLength((total * step) / 40);
190	        const point = new DOMPoint(along.x, along.y).matrixTransform(toTheScreen);
191	        const under = document.elementFromPoint(point.x, point.y);
192	        if (under?.closest(".react-flow__edge")?.getAttribute("data-id") === which) {
193	          return { x: point.x, y: point.y };
194	        }
195	      }
196	      return null;
197	    }, id);
198	    if (on !== null) {
199	      await page.mouse.click(on.x, on.y);
200	    }
201	    await arrow.focus();
202	    const standingOnIt = await page.evaluate(
203	      () => document.activeElement?.closest<HTMLElement>(".react-flow__edge")?.dataset.id,
204	    );
205	    if (standingOnIt === id) {
206	      await page.keyboard.press("Enter");
207	    }
208	    await page.keyboard.press("e");
209	    // **Which arrow the panel is open on is read off the panel itself**, from
210	    // the identifier it carries for exactly this purpose — never from its
211	    // words. The words name an arrow by the claims at its two ends, in their own
212	    // sentences, because an identifier is never put on the screen; a test that
213	    // matched those words would break the day a claim was reworded, and one that
214	    // matched an identifier in them would be asking the screen to break its rule.
215	    const about = await panel.getAttribute("data-about").catch(() => null);
216	    const said = ((await panel.textContent().catch(() => "")) ?? "").trim();
217	    if (about === id) {
218	      return;
219	    }
220	    tried.push(
221	      `point ${on === null ? "none on the glass" : `${Math.round(on.x)},${Math.round(on.y)}`}` +
222	        ` · keyboard ${standingOnIt ?? "off the map"} · panel on ${about ?? "nothing"} "${said.slice(0, 50)}"`,
223	    );
224	    await page.waitForTimeout(250);
225	  }
226	  throw new Error(
227	    `the panel never opened on ${id}. What each attempt got:\n${tried.slice(-6).join("\n")}`,
228	  );
229	}
