244	/**
245	 * Every control in the panel beside the map can actually be reached and pressed.
246	 *
247	 * **This is a geometric assertion and never a picture.** A stored screenshot
248	 * over a canvas with a background-threaded layout engine, two variable fonts and
249	 * an arrival animation is a flake generator, and this project has already paid
250	 * for chasing flakes. What it asserts instead is the thing every layout defect
251	 * the interface audit found had in common: something in the panel could be seen
252	 * in the markup and not used on the screen.
253	 *
254	 * **Three questions per control, and the third is the one that bites.**
255	 *
256	 * 1. It is drawn at a size at all.
257	 * 2. Scrolled to, it lies inside the panel's **client box** — the part of the
258	 *    panel that is actually on the glass, inside its border and beside its
259	 *    scrollbar. Scrolled out of view is fine and is why each control is scrolled
260	 *    to first: the panel scrolls as one and marks its edges, so below the fold is
261	 *    reachable. Past the left or right edge is not, because the panel does not
262	 *    scroll that way.
263	 * 3. **At its own centre, the topmost thing on the screen is the control** — or
264	 *    something inside it. That is the overlap test, and it is the only one of the
265	 *    three that catches a sibling drawn over a button, which is what "nothing is
266	 *    hidden behind anything" means. An earlier version of this helper asked only
267	 *    where boxes were, and against this stylesheet — one scrolling column whose
268	 *    sections all read `overflow: visible` — no box could ever land outside the
269	 *    content. It could not have failed.
270	 *
271	 * Each control is scrolled to over the wire and then measured in the page, which
272	 * is two round trips each rather than one for the lot. That is the price of
273	 * asking a question about what is *on the glass* rather than about what the
274	 * layout says.
275	 *
276	 * @param page The page the map is on.
277	 */
278	async function everyControlInThePanelIsWhole(page: Page): Promise<void> {
279	  const dock = page.locator(".dock");
280	  await expect(dock).toBeVisible();
281	  const controls = dock.locator("button, a, input");
282	  const many = await controls.count();
283	  expect(many, "the panel beside the map holds no controls at all").toBeGreaterThan(0);
284	
285	  const wrong: string[] = [];
286	  for (let at = 0; at < many; at += 1) {
287	    const control = controls.nth(at);
288	    // Brought onto the glass first, because the question is about what a reader
289	    // can reach and a reader scrolls. The panel is the only thing that moves.
290	    await control.scrollIntoViewIfNeeded();
291	    const verdict = await control.evaluate((element) => {
292	      const panel = element.closest<HTMLElement>(".dock");
293	      if (panel === null) {
294	        return "a control left the panel between being counted and being measured";
295	      }
296	      const name = (element.getAttribute("aria-label") ?? element.textContent ?? "")
297	        .replace(/\s+/g, " ")
298	        .trim()
299	        .slice(0, 60);
300	      const box = element.getBoundingClientRect();
301	      if (box.width === 0 || box.height === 0) {
302	        return `"${name}" is drawn at no size at all`;
303	      }
304	      // The part of the panel that is on the glass: inside its border, and
305	      // beside its scrollbar rather than under it.
306	      const frame = panel.getBoundingClientRect();
307	      const left = frame.left + panel.clientLeft;
308	      const top = frame.top + panel.clientTop;
309	      const right = left + panel.clientWidth;
310	      const bottom = top + panel.clientHeight;
311	      if (
312	        box.left < left - 1 ||
313	        box.right > right + 1 ||
314	        box.top < top - 1 ||
315	        box.bottom > bottom + 1
316	      ) {
317	        return (
318	          `"${name}" is drawn at ${Math.round(box.left)},${Math.round(box.top)} to ` +
319	          `${Math.round(box.right)},${Math.round(box.bottom)}, outside the panel's ` +
320	          `${Math.round(left)},${Math.round(top)} to ${Math.round(right)},${Math.round(bottom)} — ` +
321	          `and it had already been scrolled to`
322	        );
323	      }
324	      // **What is actually on top at its centre.** A pseudo-element with
325	      // `pointer-events: none` — the rules the panel draws at its edges — is
326	      // not an answer to this question and the browser does not give one.
327	      const onTop = document.elementFromPoint(
328	        Math.round(box.left + box.width / 2),
329	        Math.round(box.top + box.height / 2),
330	      );
331	      if (onTop === null || !(onTop === element || element.contains(onTop))) {
332	        const over =
333	          onTop === null
334	            ? "nothing at all"
335	            : `<${onTop.tagName.toLowerCase()} class="${onTop.className}">`;
336	        return `"${name}" has ${over} drawn over its own middle`;
337	      }
338	      return null;
339	    });
340	    if (verdict !== null) {
341	      wrong.push(verdict);
342	    }
343	  }
344	  expect(wrong, "controls in the panel a reader cannot reach").toEqual([]);
345	}
