1016	  // Two engine answers, one of them deliberately held, and a branch built a
1017	  // button at a time — longer than the walk the other tests take.
1018	  test.setTimeout(120_000);
1019	  await page.goto("/");
1020	  await page
1021	    .getByRole("button", { name: /Strait of Hormuz/ })
1022	    .first()
1023	    .click();
1024	  await waitForTheLayout(page, 7);
1025	
1026	  // A branch, and the news: the premium fell.
1027	  await page.locator('.react-flow__node[data-id="C"]').click();
1028	  await page.keyboard.press("b");
1029	  await page
1030	    .getByLabel(/What is this branch called/)
1031	    .fill("The premium fell, then the push changed");
1032	  await page.getByRole("button", { name: "Start this branch" }).click();
1033	  await waitForTheBranch(page, "The premium fell, then the push changed", 7);
1034	  await waitForTheAnswer(page, "Branch created. No claims moved.");
1035	
1036	  await page.locator('.react-flow__node[data-id="C"]').click();
1037	  await page.keyboard.press("e");
1038	  await expect(page.locator(".intervene")).toContainText(
1039	    "Lloyd's war-risk insurance premium for Gulf transits falls below 0.4%.",
1040	  );
1041	  await page.getByRole("button", { name: /^This happened/ }).click();
1042	  await waitForTheAnswer(page, "Branch created. Two claims moved.");
1043	  await waitForTheLayout(page, 7);
1044	
1045	  // The strait causes the premium, so it is a claim the report is evidence
1046	  // about. It must already be a claim the edit can reach.
