1048	  await expect(strait.locator(".tile")).not.toHaveAttribute("data-diff", "untouched");
1049	
1050	  // Hold the engine's next answer in flight, so the moment before it lands can
1051	  // be looked at rather than guessed at.
1052	  let holding = true;
1053	  await page.route("**/api/worlds/diff", async (route) => {
1054	    while (holding) {
1055	      await new Promise((tick) => setTimeout(tick, 50));
1056	    }
1057	    await route.continue();
