1059	
1060	  // Now change how hard the strait's opening pushes the premium.
1061	  await openThePanelOnTheArrow(page, "H->C");
1062	  // Asked for inside the panel of operations, by name. The Inspector's head
1063	  // carries a control with these same words — it is the way in, and it is not
1064	  // drawn while the panel it opens is already open — and scoping the ask here
1065	  // says which of the two this step means whatever that rule becomes.
1066	  await page
1067	    .locator(".intervene")
1068	    .getByRole("button", { name: /^Change this push/ })
1069	    .click();
1070	  await page.getByLabel(/How hard does this arrow push/).fill("3");
1071	  await page.getByRole("button", { name: "Change it to that" }).click();
1072	
1073	  // **Before the answer.** The line is already there, saying what it is waiting
1074	  // for, and the tile is the size it will keep.
1075	  const movement = strait.locator('.tile__badge[data-badge="movement"]');
1076	  await expect(movement).toBeVisible();
1077	  // Word for word the sentence the engine's own absence carries while it is
1078	  // being asked — not merely a sentence with "engine" in it, which the answer
1079	  // has too. This is what makes the two moments below two moments.
1080	  await expect(movement.locator(".tile__badge-words")).toHaveText("no engine yet");
1081	  await expect(movement).toHaveAttribute(
1082	    "title",
1083	    /has been asked at \/api\/worlds .* and has not answered/,
1084	  );
1085	  const tile = strait.locator(".tile");
1086	  const whileWaiting = await tile.evaluate((el) => (el as HTMLElement).offsetHeight);
1087	
1088	  holding = false;
1089	
1090	  // **After the answer.** The line reads the engine's own two numbers, and the
1091	  // tile is the same size it was: nothing grew when the answer landed.
1092	  await expect(movement).toHaveAttribute("title", /\.\d+.*\.\d+/);
1093	  await expect(strait).not.toContainText("no engine yet");
1094	  const said = (await movement.getAttribute("title")) ?? "";
1095	  const readings = [...said.matchAll(/(?<![\d.])\.\d+/g)].map((one) => one[0]);
1096	  expect(readings.length).toBeGreaterThanOrEqual(2);
1097	  // The two are the engine's readings of this claim, and they are not the same
1098	  // number — which is the whole point: the source moved.
1099	  expect(readings[0]).not.toBe(readings[1]);
1100	
1101	  await expect
1102	    .poll(() => tile.evaluate((el) => (el as HTMLElement).offsetHeight))
1103	    .toBe(whileWaiting);
1104	});
1105	
1106	/**
1107	 * The map keeps its arrows when the browser drops the tiles' size notifications.
1108	 *
1109	 * **This is the browser's own failure mode, made total and deterministic.** A
1110	 * `ResizeObserver` is how the drawing library learns how big a thing is, and
1111	 * when too many observations fall due in one frame the browser abandons the
1112	 * rest — *"a ResizeObserver loop completed with undelivered notifications"* —
1113	 * and an abandoned one is never delivered. #37 met that as tiles that never
1114	 * appeared, and fixed it by telling the library each tile's box outright.
1115	 *
1116	 * **A wire needs more than a box.** It is drawn between two ports — the sockets
1117	 * on a tile's edges — and where a port sits inside a tile used to be measured
1118	 * through the very same notification. So with the tiles' notifications dropped
1119	 * the map drew every claim, in its place, visible — and not one arrow. A causal
1120	 * map is its arrows: what is left is the wrong picture of the argument, and a
1121	 * silent one.
1122	 *
1123	 * **It is per tile, which is why it shows up as one missing arrow rather than
1124	 * an empty map.** Measured, dropping one tile's notifications and keeping every
1125	 * other: deafen the insurance premium and the two arrows that touch it go, and
1126	 * only those; deafen the strait and its three go. An arrow is not drawn when
1127	 * *either* end was never measured. That is the shape the end-to-end suite met
1128	 * in the wild — `H->C` absent from the glass, everything else in place — about
1129	 * once in two hundred runs at six workers on a loaded machine.
1130	 *
1131	 * **Why it passes now, and why nothing is retried to make it pass.** Every
1132	 * tile hands the drawing library its box and its four ports outright, worked
1133	 * out by `graph/ports.ts` and written onto the tile in the same numbers, so
1134	 * both ends of every arrow are known before the page has been measured once.
1135	 * With the tiles deaf, this map is drawn exactly as it is drawn with them
1136	 * hearing — which is the strongest form of the claim, and the reason nothing
1137	 * here waits or asks again.
1138	 *
1139	 * The shim below drops only the tiles' notifications and lets the glass's own
1140	 * through, because the library needs that one to draw anything at all.
1141	 */
1142	test("test_the_arrows_are_drawn_when_the_browser_drops_a_size_notification", async ({ page }) => {
1143	  await page.addInitScript(() => {
1144	    const Real = window.ResizeObserver;
1145	    // Written as a plain function rather than a class on purpose: a private
1146	    // field here is compiled to a helper the page has never heard of.
1147	    function DropsTilesNotifications(given: ResizeObserverCallback) {
1148	      const real = new Real((entries, observer) => {
1149	        const kept = entries.filter((one) => one.target.closest(".react-flow__node") === null);
1150	        if (kept.length > 0) {
1151	          given(kept, observer);
1152	        }
1153	      });
1154	      return {
1155	        observe: (target: Element, options?: ResizeObserverOptions) =>
1156	          real.observe(target, options),
1157	        unobserve: (target: Element) => real.unobserve(target),
1158	        disconnect: () => real.disconnect(),
1159	      };
1160	    }
1161	    window.ResizeObserver = DropsTilesNotifications as unknown as typeof ResizeObserver;
1162	  });
1163	
1164	  await page.goto("/");
1165	  await page
1166	    .getByRole("button", { name: /Strait of Hormuz/ })
1167	    .first()
1168	    .click();
1169	  await waitForTheLayout(page, 7);
1170	
1171	  // Every claim, visible — which is #37's half of this, and still holding.
1172	  await expect
1173	    .poll(() =>
1174	      page
1175	        .locator(".react-flow__node")
1176	        .evaluateAll(
1177	          (tiles) => tiles.filter((tile) => getComputedStyle(tile).visibility === "hidden").length,
1178	        ),
1179	    )
1180	    .toBe(0);
1181	
1182	  // And every arrow, by name — the same check the stored example gets with the
1183	  // browser behaving, so that this test says *nothing changes* rather than
1184	  // merely *something was drawn*.
1185	  await everyArrowIsDrawn(page);
