  readonly branch?: components["schemas"]["Branch"];
  /** What the map is open on: the claim or the arrow the buttons act on. */
  readonly selection: Selection;
  /** Append an edit to the open branch. */
  readonly onEdit: (edit: Edit) => void;
  /** Close the panel. */
  readonly onClose: () => void;
}

/**
 * The six things you can do to a claim, in a panel beside the map.
 *
 * Never a pop-up: it appears in the panel, the map keeps drawing beside it, and
 * closing it loses nothing because nothing is left half-done.
 */
export function InterventionPanel({
  world,
  branch,
  selection,
  onEdit,
  onClose,
}: InterventionPanelProps) {
  const [ownNumber, setOwnNumber] = useState(false);
  const [reading, setReading] = useState({ p: "", lo: "", hi: "" });
  const [pushing, setPushing] = useState(false);
  const [adding, setAdding] = useState(false);
  const [push, setPush] = useState("");
  const [said, setSaid] = useState<string | null>(null);

  /**
   * The panel takes the keyboard when it opens, and that is the reader's own
   * act rather than a theft.
   *
   * `graph/theKeyboard.ts` states the rule the map obeys: **the map takes the
   * keyboard back from nowhere, and never from somewhere.** It is about who
   * decided. A map that pulled a reader out of the palette would be taking a
   * decision they had already taken; this is the opposite — the reader pressed
   * `E`, or took up *Change this claim*, and the one thing they can have meant
   * by it is that they want to be in here.
   *
   * **Without it the keyboard is simply dropped.** The way in from the panel's
   * head unmounts the instant it is pressed, so Tab to it, press Enter, and the
   * keyboard is on nothing at all: the next Tab starts again at the top of the
   * page. The section takes focus rather than the first button, because landing
   * on *Suppose this is true* would put a reader one stray Space away from an
   * edit they did not ask for. Where the keyboard goes when this closes is the
   * screen's to answer, not this panel's, because the thing it came from may no
   * longer exist.
   */
  const panel = useRef<HTMLElement | null>(null);
  useEffect(() => {
    panel.current?.focus();
  }, []);

  const claim =
    selection?.kind === "claim" ? world.claims.find((one) => one.id === selection.id) : undefined;
  const wire =
    selection?.kind === "wire" ? world.links.find((one) => one.id === selection.id) : undefined;

  const say = (line: string) => setSaid(line);

  /**
   * Nothing here is ever disabled. A greyed-out button says "not for you" and
   * nothing else — and it is unreachable by keyboard, which makes it a control a
   * reader cannot even ask about. So a button with nothing to act on says what it
   * needs instead.
   */
  const needsAClaim = (): boolean => {
    if (claim !== undefined) {
      return false;
    }
    say(
      "Choose a claim on the map first — click it, or reach it with the keyboard and the panel " +
        "opens on it.",
    );
    return true;
  };

  /**
   * A claim named for a reader: its own words, in few enough of them to fit.
   * Never its identifier — on a generated map that is a string of machine
   * letters, and even on the stored example "H" tells a reader nothing.
   */
  const nameOf = (id: string): string => {
    const found = world.claims.find((one) => one.id === id);
    return found === undefined ? NOT_ON_THIS_MAP : inFewWords(found.claim);
  };

  return (
    <section
      className="intervene"
      ref={panel}
      // Reachable by script and never a tab stop of its own: the reader tabs
      // through the controls inside it, not through the box round them.
      tabIndex={-1}
      aria-label="Change this claim"
      // What the panel is open on, by its identifier — for a test or a tool to
      // read, the way a tile and a wire already carry theirs. An identifier is
      // never WORDS on the screen; the sentence below names the subject.
      data-about={claim?.id ?? wire?.id ?? ""}
    >
      <header className="intervene__head">
        <h2 className="intervene__heading">Change this</h2>
        <button className="intervene__close" type="button" onClick={onClose}>
          Done
        </button>
      </header>

      <p className="intervene__subject">
        {claim !== undefined
          ? claim.claim
          : wire !== undefined
            ? // An arrow is named the way the Inspector names it: by the words of
              // the claim at each end, never by an identifier. "The arrow you have
              // selected" told a reader nothing about WHICH arrow they were about
              // to change.
              `${nameOf(wire.source)} → ${nameOf(wire.target)}`

